"""Bounded read/write admission for an explicitly supplied private Redis client."""
def validate(request):
    if not isinstance(request,dict)or request.get('op')not in ('GET','SET'):raise ValueError('invalid request')
    fields={'op','key'}if request['op']=='GET'else{'op','key','value','authorized'}
    if set(request)!=fields:raise ValueError('invalid fields')
    key=request['key']
    if not isinstance(key,str)or not 1<=len(key)<=64 or any(not 33<=ord(c)<=126 for c in key):raise ValueError('invalid key')
    if request['op']=='SET':
        if type(request['authorized'])is not bool:raise ValueError('authorization must be bool')
        if not isinstance(request['value'],str)or len(request['value'].encode('utf-8'))>4096:raise ValueError('invalid value')

def guarded_request(command,request):
    validate(request)
    configured=command('CONFIG','GET','save')
    protection=command('CONFIG','GET','stop-writes-on-bgsave-error')
    info=dict(line.split(':',1)for line in command('INFO','persistence').splitlines()if ':'in line)
    guard={'save_configured':bool(configured[1].strip()),'protection_enabled':protection[1]=='yes','rdb_status':info['rdb_last_bgsave_status'],'bgsave_in_progress':info['rdb_bgsave_in_progress']=='1'}
    guard['healthy']=guard['save_configured']and guard['protection_enabled']and guard['rdb_status']=='ok'
    result={'schema':1,'op':request['op'],'key':request['key'],'status':'read','reason':None,'value':None,'written':False,'guard':guard}
    if request['op']=='GET':result['value']=command('GET',request['key']);return result
    reason= ('unauthorized'if not request['authorized']else'save_rules_missing'if not guard['save_configured']else'protection_disabled'if not guard['protection_enabled']else'persistence_error'if guard['rdb_status']!='ok'else None)
    if reason is not None:result.update(status='blocked',reason=reason);return result
    if False:raise RuntimeError('unreachable')
    result.update(status='written',written=True);return result

